// App members. Undo contains only changed generation keys, never credentials.
json recommendedUndo=json::object();std::string recommendedScope,recommendedChannel,recommendedPanel,recommendedModel;
void restoreRecommendedSettings(){if(promptComposing)return;sync();auto before=store->settings;applyModelSettings(store->settings,true);json delta=json::object();auto allowed=panelSettings();for(auto& key:allowed){auto old=before.contains(key)?before[key]:json(nullptr),now=store->settings.contains(key)?store->settings[key]:json(nullptr);if(old!=now)delta[key]={{"before",old},{"after",now}};}if(delta.empty()){status=L"이미 현재 모델의 권장값입니다.";return;}recommendedUndo=std::move(delta);recommendedScope=store->workspaceScope;recommendedChannel=store->active;recommendedPanel=store->activePanelId();recommendedModel=modelId(store->settings);store->save();rebuild(false);status=L"현재 모델의 권장값을 적용했습니다.";}
bool recommendedUndoAvailable(){return !recommendedUndo.empty()&&recommendedScope==store->workspaceScope&&recommendedChannel==store->active&&recommendedPanel==store->activePanelId()&&recommendedModel==modelId(store->settings);}
void undoRecommendedSettings(){if(promptComposing)return;sync();if(!recommendedUndoAvailable())throw std::runtime_error("현재 작업에서 되돌릴 권장값 변경이 없습니다.");for(auto it=recommendedUndo.begin();it!=recommendedUndo.end();++it){auto current=store->settings.contains(it.key())?store->settings[it.key()]:json(nullptr);if(current!=it.value()["after"])throw std::runtime_error("이후 바꾼 설정이 있어 복원을 되돌릴 수 없습니다.");}for(auto it=recommendedUndo.begin();it!=recommendedUndo.end();++it){if(it.value()["before"].is_null())store->settings.erase(it.key());else store->settings[it.key()]=it.value()["before"];}recommendedUndo=json::object();store->save();rebuild(false);status=L"권장값 적용을 되돌렸습니다.";}
